ALTER TABLE minkowski_embeddings ADD COLUMN IF NOT EXISTS preserves_additive_structure BOOLEAN;     -- Nullable: TRUE for canonical embeddings, FALSE for non-additive maps, null for unevaluated experimental rows.
ALTER TABLE minkowski_embeddings ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE minkowski_embeddings IS 'Table: MinkowskiEmbeddings. The canonical embedding σ = (σ_1, …, σ_d): K → R^d as a first-class named map. Each row binds one NumberField to (at most) one TargetLattice it produces.';
COMMENT ON COLUMN minkowski_embeddings.target_lattice IS 'Nullable: the field may have a defined embedding map even if the materialised lattice row isn''t loaded yet.';
COMMENT ON COLUMN minkowski_embeddings.is_canonical IS 'TRUE if this is the canonical Minkowski embedding.';
COMMENT ON COLUMN minkowski_embeddings.preserves_additive_structure IS 'Nullable: TRUE for canonical embeddings, FALSE for non-additive maps, null for unevaluated experimental rows.';

-- ----------------------------------------------------------------------------
-- GramMatrices: Table: GramMatrices. The Gram matrix G_ij = <e_i, e_j> for a chosen basis of a MinkowskiLattice. Matrix entries stay in MatrixJSON (ERB scalar formulas can't operate on matrices), but every scalar property derivable from G — symmetric, positive-definite, diagonal, rank-deficient — is a first-class field.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS gram_matrices (
  gram_matrix_id                      TEXT                 PRIMARY KEY
);
ALTER TABLE gram_matrices ADD COLUMN IF NOT EXISTS minkowski_lattice TEXT;
ALTER TABLE gram_matrices ADD COLUMN IF NOT EXISTS matrix_json TEXT;
ALTER TABLE gram_matrices ADD COLUMN IF NOT EXISTS is_symmetric BOOLEAN;
ALTER TABLE gram_matrices ADD COLUMN IF NOT EXISTS is_positive_definite BOOLEAN;
ALTER TABLE gram_matrices ADD COLUMN IF NOT EXISTS is_diagonal BOOLEAN;
ALTER TABLE gram_matrices ADD COLUMN IF NOT EXISTS rank_deficient BOOLEAN;
ALTER TABLE gram_matrices ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE gram_matrices IS 'Table: GramMatrices. The Gram matrix G_ij = <e_i, e_j> for a chosen basis of a MinkowskiLattice. Matrix entries stay in MatrixJSON (ERB scalar formulas can''t operate on matrices), but every scalar property derivable from G — symmetric, positive-definite, diagonal, rank-deficient — is a first-class field.';

-- ----------------------------------------------------------------------------
-- PlanarProjections: Table: PlanarProjections. The map π: lattice → R^2 that turns short lattice vectors into points in the plane. THE critical bridge from algebra to geometry. ProjectionKind tags the kind of map; downstream ProjectedShortVectors.ProjectsToUnitDistanceVector depends on this map's behaviour.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS planar_projections (
  planar_projection_id                TEXT                 PRIMARY KEY
);
ALTER TABLE planar_projections ADD COLUMN IF NOT EXISTS display_name TEXT;
ALTER TABLE planar_projections ADD COLUMN IF NOT EXISTS source_lattice TEXT;
ALTER TABLE planar_projections ADD COLUMN IF NOT EXISTS target_context TEXT;
ALTER TABLE planar_projections ADD COLUMN IF NOT EXISTS projection_kind TEXT;                       -- One of: 'first-two-coords', 'rotation-scale', 'rational-affine', 'isometric-embedding'.
ALTER TABLE planar_projections ADD COLUMN IF NOT EXISTS scaling_factor NUMERIC;
ALTER TABLE planar_projections ADD COLUMN IF NOT EXISTS rotation_degrees NUMERIC;
ALTER TABLE planar_projections ADD COLUMN IF NOT EXISTS is_isometric BOOLEAN;
ALTER TABLE planar_projections ADD COLUMN IF NOT EXISTS preserves_unit_distance BOOLEAN;            -- TRUE if vectors of squared-norm 1 in the lattice map to unit-distance vectors in R^2.
ALTER TABLE planar_projections ADD COLUMN IF NOT EXISTS projected_short_vectors TEXT;
ALTER TABLE planar_projections ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE planar_projections IS 'Table: PlanarProjections. The map π: lattice → R^2 that turns short lattice vectors into points in the plane. THE critical bridge from algebra to geometry. ProjectionKind tags the kind of map; downstream ProjectedShortVectors.ProjectsToUnitDistanceVector depends on this map''s behaviour.';
COMMENT ON COLUMN planar_projections.projection_kind IS 'One of: ''first-two-coords'', ''rotation-scale'', ''rational-affine'', ''isometric-embedding''.';
COMMENT ON COLUMN planar_projections.preserves_unit_distance IS 'TRUE if vectors of squared-norm 1 in the lattice map to unit-distance vectors in R^2.';

-- ----------------------------------------------------------------------------
-- ProjectedShortVectors: Table: ProjectedShortVectors. Each row is one ShortVector under one PlanarProjection — the point in R^2 the algebraic vector becomes. ProjectsToUnitDistanceVector is THE planar-unit target equation <π(v), π(v)> = 1 — the equation Sawin's construction is solving. Every TRUE row is one solution, contributing one unit-distance edge.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS projected_short_vectors (
  projected_short_vector_id           TEXT                 PRIMARY KEY
);
ALTER TABLE projected_short_vectors ADD COLUMN IF NOT EXISTS short_vector TEXT;
ALTER TABLE projected_short_vectors ADD COLUMN IF NOT EXISTS planar_projection TEXT;
ALTER TABLE projected_short_vectors ADD COLUMN IF NOT EXISTS projected_x NUMERIC;
ALTER TABLE projected_short_vectors ADD COLUMN IF NOT EXISTS projected_y NUMERIC;
ALTER TABLE projected_short_vectors ADD COLUMN IF NOT EXISTS unit_tolerance NUMERIC;
ALTER TABLE projected_short_vectors ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE projected_short_vectors IS 'Table: ProjectedShortVectors. Each row is one ShortVector under one PlanarProjection — the point in R^2 the algebraic vector becomes. ProjectsToUnitDistanceVector is THE planar-unit target equation <π(v), π(v)> = 1 — the equation Sawin''s construction is solving. Every TRUE row is one solution, contributing one unit-distance edge.';

-- ----------------------------------------------------------------------------
-- GolodShafarevichCriteria: Table: GolodShafarevichCriteria. The Golod–Shafarevich tower inequality, evaluated per number field. r > d^2/4 (d = minimal-generator count, r = relation count) implies an infinite class field tower — the algebraic hook used by unit-distance constructions to get many small-norm primes.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS golod_shafarevich_criteria (
  golod_shafarevich_criterion_id      TEXT                 PRIMARY KEY
);
ALTER TABLE golod_shafarevich_criteria ADD COLUMN IF NOT EXISTS number_field TEXT;
ALTER TABLE golod_shafarevich_criteria ADD COLUMN IF NOT EXISTS minimal_generator_count_d INTEGER;  -- The 'd' in the GS inequality.
ALTER TABLE golod_shafarevich_criteria ADD COLUMN IF NOT EXISTS relation_count_r INTEGER;           -- The 'r' in the GS inequality.
ALTER TABLE golod_shafarevich_criteria ADD COLUMN IF NOT EXISTS passes_criterion BOOLEAN;           -- Curator override (nullable). Null means 'use calculated SatisfiesGolodShafarevichTower'.
ALTER TABLE golod_shafarevich_criteria ADD COLUMN IF NOT EXISTS source_reference TEXT;
ALTER TABLE golod_shafarevich_criteria ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE golod_shafarevich_criteria IS 'Table: GolodShafarevichCriteria. The Golod–Shafarevich tower inequality, evaluated per number field. r > d^2/4 (d = minimal-generator count, r = relation count) implies an infinite class field tower — the algebraic hook used by unit-distance constructions to get many small-norm primes.';
COMMENT ON COLUMN golod_shafarevich_criteria.minimal_generator_count_d IS 'The ''d'' in the GS inequality.';
COMMENT ON COLUMN golod_shafarevich_criteria.relation_count_r IS 'The ''r'' in the GS inequality.';
COMMENT ON COLUMN golod_shafarevich_criteria.passes_criterion IS 'Curator override (nullable). Null means ''use calculated SatisfiesGolodShafarevichTower''.';

-- ----------------------------------------------------------------------------
-- SemanticBridges: Table: SemanticBridges. Each row is one named bridge between two domain neighborhoods — the meta-glue between regions of the model. Routing across the model goes through these bridges.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS semantic_bridges (
  semantic_bridge_id                  TEXT                 PRIMARY KEY
);
ALTER TABLE semantic_bridges ADD COLUMN IF NOT EXISTS display_name TEXT;
ALTER TABLE semantic_bridges ADD COLUMN IF NOT EXISTS from_domain TEXT;
ALTER TABLE semantic_bridges ADD COLUMN IF NOT EXISTS to_domain TEXT;
ALTER TABLE semantic_bridges ADD COLUMN IF NOT EXISTS bridge_kind TEXT;                             -- One of: embedding, projection, induction, aggregation, anchor, analogy.
ALTER TABLE semantic_bridges ADD COLUMN IF NOT EXISTS from_concept_table TEXT;
ALTER TABLE semantic_bridges ADD COLUMN IF NOT EXISTS to_concept_table TEXT;
ALTER TABLE semantic_bridges ADD COLUMN IF NOT EXISTS is_load_bearing BOOLEAN;                      -- TRUE if removing the bridge breaks the chain to the theorem; FALSE for analogy-only; null when unclassified.
ALTER TABLE semantic_bridges ADD COLUMN IF NOT EXISTS is_closed BOOLEAN;                            -- TRUE if every row in FromConceptTable has a witness in ToConceptTable; null when not checked.
ALTER TABLE semantic_bridges ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE semantic_bridges IS 'Table: SemanticBridges. Each row is one named bridge between two domain neighborhoods — the meta-glue between regions of the model. Routing across the model goes through these bridges.';
COMMENT ON COLUMN semantic_bridges.bridge_kind IS 'One of: embedding, projection, induction, aggregation, anchor, analogy.';
COMMENT ON COLUMN semantic_bridges.is_load_bearing IS 'TRUE if removing the bridge breaks the chain to the theorem; FALSE for analogy-only; null when unclassified.';
COMMENT ON COLUMN semantic_bridges.is_closed IS 'TRUE if every row in FromConceptTable has a witness in ToConceptTable; null when not checked.';

-- ----------------------------------------------------------------------------
-- SemanticRoutes: Table: SemanticRoutes. Named end-to-end paths through the model. The 'full semantic spine' is the route NumberFields → Theorems through every bridge.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS semantic_routes (
  semantic_route_id                   TEXT                 PRIMARY KEY
);
ALTER TABLE semantic_routes ADD COLUMN IF NOT EXISTS display_name TEXT;
ALTER TABLE semantic_routes ADD COLUMN IF NOT EXISTS start_concept TEXT;
ALTER TABLE semantic_routes ADD COLUMN IF NOT EXISTS end_concept TEXT;
ALTER TABLE semantic_routes ADD COLUMN IF NOT EXISTS steps TEXT;
ALTER TABLE semantic_routes ADD COLUMN IF NOT EXISTS is_full_spine BOOLEAN;
ALTER TABLE semantic_routes ADD COLUMN IF NOT EXISTS ends_at_theorem_anchor BOOLEAN;
ALTER TABLE semantic_routes ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE semantic_routes IS 'Table: SemanticRoutes. Named end-to-end paths through the model. The ''full semantic spine'' is the route NumberFields → Theorems through every bridge.';

-- ----------------------------------------------------------------------------
-- SemanticRouteSteps: Table: SemanticRouteSteps. The ordered inference steps that make up a SemanticRoute. Each step optionally invokes a SemanticBridge.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS semantic_route_steps (
  semantic_route_step_id              TEXT                 PRIMARY KEY
);
ALTER TABLE semantic_route_steps ADD COLUMN IF NOT EXISTS semantic_route TEXT;
ALTER TABLE semantic_route_steps ADD COLUMN IF NOT EXISTS step_order INTEGER;
ALTER TABLE semantic_route_steps ADD COLUMN IF NOT EXISTS from_concept TEXT;
ALTER TABLE semantic_route_steps ADD COLUMN IF NOT EXISTS to_concept TEXT;
ALTER TABLE semantic_route_steps ADD COLUMN IF NOT EXISTS bridge_used TEXT;                         -- Null when this step is an intra-domain FK hop; set when crossing domains.
ALTER TABLE semantic_route_steps ADD COLUMN IF NOT EXISTS is_validated BOOLEAN;                     -- Curator-set: TRUE if verified, FALSE if known broken, null if not yet evaluated.
ALTER TABLE semantic_route_steps ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE semantic_route_steps IS 'Table: SemanticRouteSteps. The ordered inference steps that make up a SemanticRoute. Each step optionally invokes a SemanticBridge.';
COMMENT ON COLUMN semantic_route_steps.bridge_used IS 'Null when this step is an intra-domain FK hop; set when crossing domains.';
COMMENT ON COLUMN semantic_route_steps.is_validated IS 'Curator-set: TRUE if verified, FALSE if known broken, null if not yet evaluated.';

-- ----------------------------------------------------------------------------
-- SourceReferences: Table: SourceReferences. The bibliography. Every lemma, theorem, and bound points at exactly one SourceReference row.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS source_references (
  source_reference_id                 TEXT                 PRIMARY KEY
);
ALTER TABLE source_references ADD COLUMN IF NOT EXISTS short_label TEXT;
ALTER TABLE source_references ADD COLUMN IF NOT EXISTS full_citation TEXT;
ALTER TABLE source_references ADD COLUMN IF NOT EXISTS url TEXT;
ALTER TABLE source_references ADD COLUMN IF NOT EXISTS year INTEGER;
ALTER TABLE source_references ADD COLUMN IF NOT EXISTS is_arxiv BOOLEAN;
ALTER TABLE source_references ADD COLUMN IF NOT EXISTS is_published BOOLEAN;
ALTER TABLE source_references ADD COLUMN IF NOT EXISTS valid_from DATE;                             -- ISO publication date — the moment this source becomes citable.
ALTER TABLE source_references ADD COLUMN IF NOT EXISTS valid_to DATE;                               -- ISO retraction date (if any). Null = still in good standing.
ALTER TABLE source_references ADD COLUMN IF NOT EXISTS tx_from DATE;
ALTER TABLE source_references ADD COLUMN IF NOT EXISTS tx_to TEXT;
ALTER TABLE source_references ADD COLUMN IF NOT EXISTS is_currently_valid BOOLEAN;                  -- TRUE if the source is still in good standing; FALSE if retracted; null if standing not yet evaluated.
ALTER TABLE source_references ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE source_references IS 'Table: SourceReferences. The bibliography. Every lemma, theorem, and bound points at exactly one SourceReference row.';
COMMENT ON COLUMN source_references.valid_from IS 'ISO publication date — the moment this source becomes citable.';
COMMENT ON COLUMN source_references.valid_to IS 'ISO retraction date (if any). Null = still in good standing.';
COMMENT ON COLUMN source_references.is_currently_valid IS 'TRUE if the source is still in good standing; FALSE if retracted; null if standing not yet evaluated.';

-- ----------------------------------------------------------------------------
-- Lemmas: Table: Lemmas. Extracted named statements from source references. FeedsObjectTable + FeedsObjectId point at the row this lemma underwrites.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS lemmas (
  lemma_id                            TEXT                 PRIMARY KEY
);
ALTER TABLE lemmas ADD COLUMN IF NOT EXISTS label TEXT;
ALTER TABLE lemmas ADD COLUMN IF NOT EXISTS source_reference TEXT;
ALTER TABLE lemmas ADD COLUMN IF NOT EXISTS statement_text TEXT;
ALTER TABLE lemmas ADD COLUMN IF NOT EXISTS feeds_object_table TEXT;
ALTER TABLE lemmas ADD COLUMN IF NOT EXISTS feeds_object_id TEXT;
ALTER TABLE lemmas ADD COLUMN IF NOT EXISTS is_loaded BOOLEAN;                                      -- TRUE if the lemma's content has been turned into data; FALSE if known but not loaded; null if unevaluated.
ALTER TABLE lemmas ADD COLUMN IF NOT EXISTS is_load_bearing BOOLEAN;
ALTER TABLE lemmas ADD COLUMN IF NOT EXISTS valid_from DATE;                                        -- ISO date this lemma was first asserted (inherits from SourceReference).
ALTER TABLE lemmas ADD COLUMN IF NOT EXISTS valid_to DATE;
ALTER TABLE lemmas ADD COLUMN IF NOT EXISTS tx_from DATE;
ALTER TABLE lemmas ADD COLUMN IF NOT EXISTS tx_to TEXT;
ALTER TABLE lemmas ADD COLUMN IF NOT EXISTS is_currently_valid BOOLEAN;                             -- TRUE if the lemma is still considered valid; FALSE if refuted/retracted; null if unevaluated.
ALTER TABLE lemmas ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE lemmas IS 'Table: Lemmas. Extracted named statements from source references. FeedsObjectTable + FeedsObjectId point at the row this lemma underwrites.';
COMMENT ON COLUMN lemmas.is_loaded IS 'TRUE if the lemma''s content has been turned into data; FALSE if known but not loaded; null if unevaluated.';
COMMENT ON COLUMN lemmas.valid_from IS 'ISO date this lemma was first asserted (inherits from SourceReference).';
COMMENT ON COLUMN lemmas.is_currently_valid IS 'TRUE if the lemma is still considered valid; FALSE if refuted/retracted; null if unevaluated.';

-- ----------------------------------------------------------------------------
-- MirrorContract: Table: MirrorContract. The five-rule contract from THE_PLAN.md §3.1 governing how the rulebook mirrors the math. Each rule is a row so agents and substrates can quote it back rather than reading the markdown.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS mirror_contract (
  mirror_contract_id                  TEXT                 PRIMARY KEY
);
ALTER TABLE mirror_contract ADD COLUMN IF NOT EXISTS rule_label TEXT;
ALTER TABLE mirror_contract ADD COLUMN IF NOT EXISTS rule_statement TEXT;
ALTER TABLE mirror_contract ADD COLUMN IF NOT EXISTS rule_kind TEXT;                                -- One of: load, describe, derive, gate, reject.
ALTER TABLE mirror_contract ADD COLUMN IF NOT EXISTS applies_to_scope TEXT;
ALTER TABLE mirror_contract ADD COLUMN IF NOT EXISTS is_binding_on_agents BOOLEAN;                  -- TRUE if agents must follow this rule; FALSE if deprecated; null if under discussion.
ALTER TABLE mirror_contract ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE mirror_contract IS 'Table: MirrorContract. The five-rule contract from THE_PLAN.md §3.1 governing how the rulebook mirrors the math. Each rule is a row so agents and substrates can quote it back rather than reading the markdown.';
COMMENT ON COLUMN mirror_contract.rule_kind IS 'One of: load, describe, derive, gate, reject.';
COMMENT ON COLUMN mirror_contract.is_binding_on_agents IS 'TRUE if agents must follow this rule; FALSE if deprecated; null if under discussion.';

-- ----------------------------------------------------------------------------
-- Conjectures: Table: Conjectures. Open and resolved conjectures about an AsymptoticFunction — distinct from Theorems (which are proved) because a conjecture is named, has a target exponent, and carries a resolution status that may change over time. Erdős's polynomial-improvement conjecture sits here; Sawin's resolved-as-proved conjecture-then-theorem is cross-referenced.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS conjectures (
  conjecture_id                       TEXT                 PRIMARY KEY
);
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS display_name TEXT;
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS statement_text TEXT;
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS target_function TEXT;
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS conjectured_exponent NUMERIC;                      -- The exponent the conjecture asserts. Null when the conjecture is non-exponent (e.g., a structural claim).
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS is_conjectural_upper_bound BOOLEAN;
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS is_conjectural_lower_bound BOOLEAN;
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS proposed_by TEXT;
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS is_resolved BOOLEAN;                               -- TRUE if proved/disproved; FALSE if explicitly still open; null when status hasn't been classified.
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS resolved_as TEXT;                                  -- One of: 'proved', 'disproved', 'withdrawn'. Null when not resolved.
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS resolution_citation TEXT;
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS related_theorem TEXT;                              -- If this conjecture resolved into a theorem, the theorem row is here.
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS valid_from DATE;                                   -- ISO date this conjecture was first proposed.
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS valid_to DATE;                                     -- ISO date this conjecture left open status (resolved or withdrawn). Null = still open.
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS tx_from DATE;
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS tx_to TEXT;
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS is_currently_valid BOOLEAN;                        -- TRUE iff the conjecture is still an OPEN question. Resolved or withdrawn ⇒ FALSE. Null = unevaluated. NOTE: this is bitemporal-status, NOT the truth of the underlying proposition — a conjecture-that-became-a-theorem has IsCurrentlyValid=FALSE here but the proposition itself is now TRUE in Theorems.
ALTER TABLE conjectures ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE conjectures IS 'Table: Conjectures. Open and resolved conjectures about an AsymptoticFunction — distinct from Theorems (which are proved) because a conjecture is named, has a target exponent, and carries a resolution status that may change over time. Erdős''s polynomial-improvement conjecture sits here; Sawin''s resolved-as-proved conjecture-then-theorem is cross-referenced.';
COMMENT ON COLUMN conjectures.conjectured_exponent IS 'The exponent the conjecture asserts. Null when the conjecture is non-exponent (e.g., a structural claim).';
COMMENT ON COLUMN conjectures.is_resolved IS 'TRUE if proved/disproved; FALSE if explicitly still open; null when status hasn''t been classified.';
COMMENT ON COLUMN conjectures.resolved_as IS 'One of: ''proved'', ''disproved'', ''withdrawn''. Null when not resolved.';
COMMENT ON COLUMN conjectures.related_theorem IS 'If this conjecture resolved into a theorem, the theorem row is here.';
COMMENT ON COLUMN conjectures.valid_from IS 'ISO date this conjecture was first proposed.';
COMMENT ON COLUMN conjectures.valid_to IS 'ISO date this conjecture left open status (resolved or withdrawn). Null = still open.';
COMMENT ON COLUMN conjectures.is_currently_valid IS 'TRUE iff the conjecture is still an OPEN question. Resolved or withdrawn ⇒ FALSE. Null = unevaluated. NOTE: this is bitemporal-status, NOT the truth of the underlying proposition — a conjecture-that-became-a-theorem has IsCurrentlyValid=FALSE here but the proposition itself is now TRUE in Theorems.';

-- ----------------------------------------------------------------------------
-- ProofObligations: Table: ProofObligations. Bidirectional links between AsymptoticLowerBounds and the Lemmas that must be loaded for the bound to be derivable. Each row says 'bound X depends on lemma Y'. Aggregations on the bound side surface how many obligations are open vs satisfied.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS proof_obligations (
  proof_obligation_id                 TEXT                 PRIMARY KEY
);
ALTER TABLE proof_obligations ADD COLUMN IF NOT EXISTS parent_bound TEXT;
ALTER TABLE proof_obligations ADD COLUMN IF NOT EXISTS required_lemma TEXT;
ALTER TABLE proof_obligations ADD COLUMN IF NOT EXISTS obligation_kind TEXT;                        -- One of: 'necessary', 'sufficient', 'auxiliary'.
ALTER TABLE proof_obligations ADD COLUMN IF NOT EXISTS is_satisfied BOOLEAN;                        -- TRUE if the curator has confirmed the lemma justifies its part of the bound; FALSE if known gap; null if unevaluated.
ALTER TABLE proof_obligations ADD COLUMN IF NOT EXISTS valid_from DATE;
ALTER TABLE proof_obligations ADD COLUMN IF NOT EXISTS valid_to DATE;
ALTER TABLE proof_obligations ADD COLUMN IF NOT EXISTS tx_from DATE;
ALTER TABLE proof_obligations ADD COLUMN IF NOT EXISTS tx_to TEXT;
ALTER TABLE proof_obligations ADD COLUMN IF NOT EXISTS is_currently_valid BOOLEAN;
ALTER TABLE proof_obligations ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE proof_obligations IS 'Table: ProofObligations. Bidirectional links between AsymptoticLowerBounds and the Lemmas that must be loaded for the bound to be derivable. Each row says ''bound X depends on lemma Y''. Aggregations on the bound side surface how many obligations are open vs satisfied.';
COMMENT ON COLUMN proof_obligations.obligation_kind IS 'One of: ''necessary'', ''sufficient'', ''auxiliary''.';
COMMENT ON COLUMN proof_obligations.is_satisfied IS 'TRUE if the curator has confirmed the lemma justifies its part of the bound; FALSE if known gap; null if unevaluated.';

-- ----------------------------------------------------------------------------
-- CitationLinks: Table: CitationLinks. Directed graph of citations and dependencies between SourceReferences. CitationKind classifies whether the citing source extends, improves, depends on, or merely cites the cited source.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS citation_links (
  citation_link_id                    TEXT                 PRIMARY KEY
);
ALTER TABLE citation_links ADD COLUMN IF NOT EXISTS citing_source TEXT;
ALTER TABLE citation_links ADD COLUMN IF NOT EXISTS cited_source TEXT;
ALTER TABLE citation_links ADD COLUMN IF NOT EXISTS citation_kind TEXT;                             -- One of: 'extends', 'improves', 'cites-for-context', 'depends-on', 'disagrees-with'.
ALTER TABLE citation_links ADD COLUMN IF NOT EXISTS is_load_bearing BOOLEAN;                        -- TRUE if removing the cited source breaks the citing source's proof; FALSE for context-only; null when unclassified.
ALTER TABLE citation_links ADD COLUMN IF NOT EXISTS valid_from DATE;                                -- ISO date this citation became real (matches the citing source's publication date).
ALTER TABLE citation_links ADD COLUMN IF NOT EXISTS valid_to DATE;
ALTER TABLE citation_links ADD COLUMN IF NOT EXISTS tx_from DATE;
ALTER TABLE citation_links ADD COLUMN IF NOT EXISTS tx_to TEXT;
ALTER TABLE citation_links ADD COLUMN IF NOT EXISTS is_currently_valid BOOLEAN;                     -- TRUE iff both the citing and cited sources are themselves still currently valid; FALSE if either has been retracted; null if unevaluated.
ALTER TABLE citation_links ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE citation_links IS 'Table: CitationLinks. Directed graph of citations and dependencies between SourceReferences. CitationKind classifies whether the citing source extends, improves, depends on, or merely cites the cited source.';
COMMENT ON COLUMN citation_links.citation_kind IS 'One of: ''extends'', ''improves'', ''cites-for-context'', ''depends-on'', ''disagrees-with''.';
COMMENT ON COLUMN citation_links.is_load_bearing IS 'TRUE if removing the cited source breaks the citing source''s proof; FALSE for context-only; null when unclassified.';
COMMENT ON COLUMN citation_links.valid_from IS 'ISO date this citation became real (matches the citing source''s publication date).';
COMMENT ON COLUMN citation_links.is_currently_valid IS 'TRUE iff both the citing and cited sources are themselves still currently valid; FALSE if either has been retracted; null if unevaluated.';

-- ----------------------------------------------------------------------------
-- AnswerKey: Table: AnswerKey. The §14 substrate-equivalence gate from THE_PLAN.md. Each row pins ONE cell (TargetTable + TargetRowId + TargetField) to its expected value. Every conformance-tested substrate (Postgres, Python, OWL, …) must reproduce these values; any mismatch with GateLevel='blocking' fails the build.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS answer_key (
  answer_key_id                       TEXT                 PRIMARY KEY
);
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS target_table TEXT;
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS target_row_id TEXT;
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS target_field TEXT;
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS data_type TEXT;                                     -- One of: 'string', 'number', 'boolean'.
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS expected_string TEXT;
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS expected_number NUMERIC;
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS expected_boolean BOOLEAN;
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS tolerance NUMERIC;                                  -- Numeric tolerance for floating-point comparisons. Null for exact-match.
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS gate_level TEXT;                                    -- One of: 'blocking', 'warning', 'info'.
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS is_currently_matched BOOLEAN;                       -- TRUE if the most recent substrate run matched the expected value; FALSE if it didn't; null if not yet run.
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS valid_from DATE;                                    -- ISO date when this expected-value pin was first asserted.
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS valid_to DATE;                                      -- ISO date when this pin was retired/changed.
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS tx_from DATE;
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS tx_to TEXT;
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS is_currently_valid BOOLEAN;                         -- TRUE if the pin is still the active expected value; FALSE if superseded by a newer pin; null if unevaluated.
ALTER TABLE answer_key ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE answer_key IS 'Table: AnswerKey. The §14 substrate-equivalence gate from THE_PLAN.md. Each row pins ONE cell (TargetTable + TargetRowId + TargetField) to its expected value. Every conformance-tested substrate (Postgres, Python, OWL, …) must reproduce these values; any mismatch with GateLevel=''blocking'' fails the build.';
COMMENT ON COLUMN answer_key.data_type IS 'One of: ''string'', ''number'', ''boolean''.';
COMMENT ON COLUMN answer_key.tolerance IS 'Numeric tolerance for floating-point comparisons. Null for exact-match.';
COMMENT ON COLUMN answer_key.gate_level IS 'One of: ''blocking'', ''warning'', ''info''.';
COMMENT ON COLUMN answer_key.is_currently_matched IS 'TRUE if the most recent substrate run matched the expected value; FALSE if it didn''t; null if not yet run.';
COMMENT ON COLUMN answer_key.valid_from IS 'ISO date when this expected-value pin was first asserted.';
COMMENT ON COLUMN answer_key.valid_to IS 'ISO date when this pin was retired/changed.';
COMMENT ON COLUMN answer_key.is_currently_valid IS 'TRUE if the pin is still the active expected value; FALSE if superseded by a newer pin; null if unevaluated.';

-- ----------------------------------------------------------------------------
-- TemporalSnapshots: Table: TemporalSnapshots. Named moments in the historical progression of the unit-distance problem. Each row pins a calendar date with a label so chronology becomes a first-class entity. Aggregations against bitemporal columns elsewhere in the rulebook can reference these moments by name instead of by raw ISO string.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS temporal_snapshots (
  temporal_snapshot_id                TEXT                 PRIMARY KEY
);
ALTER TABLE temporal_snapshots ADD COLUMN IF NOT EXISTS label TEXT;
ALTER TABLE temporal_snapshots ADD COLUMN IF NOT EXISTS snapshot_date DATE;                         -- ISO date for the moment this snapshot captures.
ALTER TABLE temporal_snapshots ADD COLUMN IF NOT EXISTS description TEXT;
ALTER TABLE temporal_snapshots ADD COLUMN IF NOT EXISTS is_historical BOOLEAN;                      -- TRUE for past moments; FALSE for the current moment; null for future-projected moments.
ALTER TABLE temporal_snapshots ADD COLUMN IF NOT EXISTS anchoring_source_reference TEXT;            -- The source whose publication date pins this moment, when applicable.
COMMENT ON TABLE temporal_snapshots IS 'Table: TemporalSnapshots. Named moments in the historical progression of the unit-distance problem. Each row pins a calendar date with a label so chronology becomes a first-class entity. Aggregations against bitemporal columns elsewhere in the rulebook can reference these moments by name instead of by raw ISO string.';
COMMENT ON COLUMN temporal_snapshots.snapshot_date IS 'ISO date for the moment this snapshot captures.';
COMMENT ON COLUMN temporal_snapshots.is_historical IS 'TRUE for past moments; FALSE for the current moment; null for future-projected moments.';
COMMENT ON COLUMN temporal_snapshots.anchoring_source_reference IS 'The source whose publication date pins this moment, when applicable.';

-- ----------------------------------------------------------------------------
-- LowerBoundValidityAtSnapshot: Table: LowerBoundValidityAtSnapshot. Junction between AsymptoticLowerBounds and TemporalSnapshots — one row per (bound × snapshot) pair recording whether the bound was bitemporally valid at that moment. Pre-computed because ERB's MAXIFS filters on equality, not on date ranges; this junction makes 'as-of' rollups expressible as plain aggregations on TemporalSnapshots.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS lower_bound_validity_at_snapshot (
  lower_bound_validity_at_snapshot_id TEXT                 PRIMARY KEY
);
ALTER TABLE lower_bound_validity_at_snapshot ADD COLUMN IF NOT EXISTS asymptotic_lower_bound TEXT;
ALTER TABLE lower_bound_validity_at_snapshot ADD COLUMN IF NOT EXISTS temporal_snapshot TEXT;
ALTER TABLE lower_bound_validity_at_snapshot ADD COLUMN IF NOT EXISTS is_valid_at_this_snapshot BOOLEAN;-- TRUE iff the bound's [ValidFrom, ValidTo) interval contains the SnapshotDate. Pre-computed since ERB MAXIFS doesn't support range filters; substrate-side temporal queries can re-derive this if needed.
ALTER TABLE lower_bound_validity_at_snapshot ADD COLUMN IF NOT EXISTS description TEXT;             -- Free-text annotation for this row.
COMMENT ON TABLE lower_bound_validity_at_snapshot IS 'Table: LowerBoundValidityAtSnapshot. Junction between AsymptoticLowerBounds and TemporalSnapshots — one row per (bound × snapshot) pair recording whether the bound was bitemporally valid at that moment. Pre-computed because ERB''s MAXIFS filters on equality, not on date ranges; this junction makes ''as-of'' rollups expressible as plain aggregations on TemporalSnapshots.';
COMMENT ON COLUMN lower_bound_validity_at_snapshot.is_valid_at_this_snapshot IS 'TRUE iff the bound''s [ValidFrom, ValidTo) interval contains the SnapshotDate. Pre-computed since ERB MAXIFS doesn''t support range filters; substrate-side temporal queries can re-derive this if needed.';
COMMENT ON COLUMN lower_bound_validity_at_snapshot.description IS 'Free-text annotation for this row.';

