-- calc_minkowski_lattices_determinant_squared
-- Field: MinkowskiLattices.DeterminantSquared
-- Type: calculated | DataType: decimal | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_minkowski_lattices_determinant_squared(p_minkowski_lattice_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (POWER(((SELECT determinant FROM minkowski_lattices WHERE minkowski_lattice_id = p_minkowski_lattice_id))::NUMERIC, (2)::NUMERIC))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_minkowski_lattices_absolute_field_discriminant
-- Field: MinkowskiLattices.AbsoluteFieldDiscriminant
-- Type: calculated | DataType: decimal | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_minkowski_lattices_absolute_field_discriminant(p_minkowski_lattice_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (ABS(calc_minkowski_lattices_field_discriminant(p_minkowski_lattice_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_minkowski_lattices_determinant_squared_equals_discriminant
-- Field: MinkowskiLattices.DeterminantSquaredEqualsDiscriminant
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_minkowski_lattices_determinant_squared_equals_discriminant(p_minkowski_lattice_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_minkowski_lattices_determinant_squared(p_minkowski_lattice_id)) AS v) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_minkowski_lattices_absolute_field_discriminant(p_minkowski_lattice_id)) AS v) __safe_numeric), 0))))::NUMERIC < 0.0001)::boolean;
$$ LANGUAGE sql STABLE;

