RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM proof_obligations WHERE parent_bound = (SELECT NULLIF(asymptotic_lower_bound_id, '') FROM asymptotic_lower_bounds WHERE asymptotic_lower_bound_id = p_asymptotic_lower_bound_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_asymptotic_lower_bounds_satisfied_obligation_count
