-- calc_golod_shafarevich_criteria_name
-- Field: GolodShafarevichCriteria.Name
-- Type: calculated | DataType: string | Returns: TEXT

CREATE OR REPLACE FUNCTION calc_golod_shafarevich_criteria_name(p_golod_shafarevich_criterion_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(number_field, '') FROM golod_shafarevich_criteria WHERE golod_shafarevich_criterion_id = p_golod_shafarevich_criterion_id), '-gs'))::text;
$$ LANGUAGE sql STABLE;

-- calc_golod_shafarevich_criteria_criterion_threshold
-- Field: GolodShafarevichCriteria.CriterionThreshold
-- Type: calculated | DataType: decimal | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_golod_shafarevich_criteria_criterion_threshold(p_golod_shafarevich_criterion_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (POWER(((SELECT minimal_generator_count_d FROM golod_shafarevich_criteria WHERE golod_shafarevich_criterion_id = p_golod_shafarevich_criterion_id))::NUMERIC, (2)::NUMERIC)) AS v) __safe_numeric), 0) / NULLIF(COALESCE(4, 0), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_golod_shafarevich_criteria_relation_count_exceeds_threshol
-- Field: GolodShafarevichCriteria.RelationCountExceedsThreshold
-- Type: calculated | DataType: boolean | Returns: BOOLEAN

CREATE OR REPLACE FUNCTION calc_golod_shafarevich_criteria_relation_count_exceeds_threshol(p_golod_shafarevich_criterion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT relation_count_r FROM golod_shafarevich_criteria WHERE golod_shafarevich_criterion_id = p_golod_shafarevich_criterion_id) > calc_golod_shafarevich_criteria_criterion_threshold(p_golod_shafarevich_criterion_id))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_golod_shafarevich_criteria_satisfies_golod_shafarevich_tow
-- Field: GolodShafarevichCriteria.SatisfiesGolodShafarevichTower
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_golod_shafarevich_criteria_satisfies_golod_shafarevich_tow(p_golod_shafarevich_criterion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (calc_golod_shafarevich_criteria_relation_count_exceeds_threshol(p_golod_shafarevich_criterion_id))::boolean;
$$ LANGUAGE sql STABLE;

